package com.cloudmall.order;
import com.cloudmall.common.api.*;import com.cloudmall.common.error.*;import org.springframework.web.bind.annotation.*;import java.math.*;import java.time.*;import java.time.format.*;import java.util.*;import java.util.concurrent.*;
@RestController @RequestMapping("/api") public class OrderController{static final Map<String,Order> ORDERS=new ConcurrentHashMap<>();static final Map<String,String> IDEM=new ConcurrentHashMap<>();
 @PostMapping("/orders")public ApiResponse<?> create(@RequestHeader("Idempotency-Key")String key,@RequestBody CreateRequest r){if(key.trim().isEmpty())throw new BizException(ErrorCodes.INVALID,"Idempotency-Key不能为空",400);if(IDEM.containsKey(key))return ApiResponse.ok(ORDERS.get(IDEM.get(key)));if(r.items==null||r.items.isEmpty())throw new BizException(ErrorCodes.INVALID,"订单不能为空",400);String no=YearMonth.now().format(DateTimeFormatter.ofPattern("yyyyMM"))+UUID.randomUUID().toString().replace("-","");Order o=new Order(no,"PENDING_PAYMENT",new BigDecimal("0.00"));for(Item i:r.items)o.payAmount=o.payAmount.add(BigDecimal.valueOf(i.quantity));ORDERS.put(no,o);IDEM.put(key,no);return ApiResponse.ok(o);}
 @GetMapping("/orders")public ApiResponse<?> list(@RequestParam(required=false)String status,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){List<Order>x=new ArrayList<>();for(Order o:ORDERS.values())if(status==null||status.equals(o.status))x.add(o);return ApiResponse.ok(new PageResult<>(x,page,pageSize,x.size()));}@GetMapping("/orders/{no}")public ApiResponse<?> get(@PathVariable String no){Order o=ORDERS.get(no);if(o==null)throw new BizException(ErrorCodes.NOT_FOUND,"订单不存在",404);return ApiResponse.ok(o);}
 @PostMapping("/orders/{no}/cancel")public ApiResponse<?> cancel(@PathVariable String no){Order o=must(no);if(!"PENDING_PAYMENT".equals(o.status))throw new BizException(ErrorCodes.STATUS,"订单状态不允许取消",409);o.status="CANCELLED";return ApiResponse.ok(o);}@PostMapping("/orders/{no}/confirm")public ApiResponse<?> confirm(@PathVariable String no){Order o=must(no);if(!"PAID".equals(o.status))throw new BizException(ErrorCodes.STATUS,"订单尚未支付",409);o.status="COMPLETED";return ApiResponse.ok(o);}
 public static Order must(String no){Order o=ORDERS.get(no);if(o==null)throw new BizException(ErrorCodes.NOT_FOUND,"订单不存在",404);return o;}public static class CreateRequest{public List<Item>items;public Long addressId;}public static class Item{public Long skuId;public int quantity;}public static class Order{public String orderNo,status;public BigDecimal payAmount;public String createdAt=OffsetDateTime.now().toString();Order(String n,String s,BigDecimal a){orderNo=n;status=s;payAmount=a;}}
}
